import{_ as a,C as s,o as d,c as n,j as t,a as o,E as c,ag as i}from"./chunks/framework.HG0H2VLS.js";const y=JSON.parse('{"title":"ExportScreen","description":"","frontmatter":{},"headers":[],"relativePath":"cc-templates/export-screen.md","filePath":"cc-templates/export-screen.md"}'),l={name:"cc-templates/export-screen.md"};function p(u,e,h,m,g,x){const r=s("ComponentDemo");return d(),n("div",null,[e[0]||(e[0]=t("hr",null,null,-1)),e[1]||(e[1]=t("h2",{id:"title-exportscreen",tabindex:"-1"},[o("title: ExportScreen "),t("a",{class:"header-anchor",href:"#title-exportscreen","aria-label":'Permalink to "title: ExportScreen"'},"​")],-1)),e[2]||(e[2]=t("h1",{id:"exportscreen",tabindex:"-1"},[o("ExportScreen "),t("a",{class:"header-anchor",href:"#exportscreen","aria-label":'Permalink to "ExportScreen"'},"​")],-1)),e[3]||(e[3]=t("blockquote",null,[t("p",null,"the v3 Export pattern: v1's filter groups as a flush Accordion + scope, Columns (presets + Choose columns, new), sticky Your export summary (live count, applied filters with ×, columns, Format SegmentedControl, Export), Your recent exports (progress / Ready + Download / Expired, new)")],-1)),c(r,{src:"/demos/src/cc/templates/ExportScreen/ExportScreen.html"}),e[4]||(e[4]=i('<h2 id="v1-s-shape-every-export-read" tabindex="-1">v1&#39;s shape (every export read) <a class="header-anchor" href="#v1-s-shape-every-export-read" aria-label="Permalink to &quot;v1&#39;s shape (every export read)&quot;">​</a></h2><p>A filter form, often split by &quot;Comment&quot; rows into titled groups; a <strong>File Format</strong> select (xlsx, csv, tsv); Export creates a <strong>scheduled task</strong> and says &quot;…has been scheduled and you will be emailed once it is complete&quot;; v1&#39;s TaskProgress panel lists runs in progress. No v1 export lets you pick columns; User Export has two presets (All / Contact details only).</p><h2 id="the-page-mark-s-choices-22-oct-2026" tabindex="-1">The page (Mark&#39;s choices, 22 Oct 2026) <a class="header-anchor" href="#the-page-mark-s-choices-22-oct-2026" aria-label="Permalink to &quot;The page (Mark&#39;s choices, 22 Oct 2026)&quot;">​</a></h2><ol><li><strong>One page + a sticky summary</strong>, no stepper: an export is one decision.</li><li><strong>Columns: presets + &quot;Choose columns&quot;</strong> (new): a checklist grouped by area, with search, a per-group All, and a running &quot;n of N columns chosen&quot;.</li><li><strong>Email + &quot;Your recent exports&quot;</strong> (new): finished files can be downloaded on the page for 7 days; a running export shows its progress in the same card (this replaces v1&#39;s in-progress panel).</li><li><strong>Live count</strong> (new): &quot;27,480 contacts match these filters&quot;, recounted 350ms after any change; at 0 the summary says so and Export is disabled.</li></ol><table tabindex="0"><thead><tr><th>Region</th><th>Content</th></tr></thead><tbody><tr><td>Result slot</td><td>&quot;Export started…&quot; (success Alert) after a run</td></tr><tr><td>Your recent exports</td><td>File (name + &quot;From … · n filters · n columns&quot;), count, Format, Run by, Started, Status (progress bar / Ready + &quot;Kept until …&quot; / Expired), Download</td></tr><tr><td>Filters card</td><td>A one-line rule (&quot;Leave a filter empty…&quot;), the <strong>scope</strong> (Registration zone / Zone), then v1&#39;s groups as a flush <strong>Accordion</strong>; each group head shows a count chip when any of its filters is set</td></tr><tr><td>Columns card</td><td>Preset radios with what they hold and how many columns; the picker for &quot;Choose columns&quot;; <strong>Also include</strong> rows (v1 &quot;Include …&quot; options that add columns)</td></tr><tr><td>Your export (summary)</td><td>Count · From · Filters (each with ×, Clear all) · Columns (+ Change, jumps to the card) · Format (SegmentedControl XLSX / CSV / TSV, plus the export&#39;s format options) · Export N contacts + a note on how it runs</td></tr></tbody></table><p><strong>Converting a v1 export:</strong> &quot;cm&quot; rows → group titles; filter rows → FieldRows in that group; rows that add columns (&quot;Include Activity Data&quot;, &quot;Include All Subscription Plans&quot;, &quot;Include Reviews&quot;) → Columns › Also include; &quot;File Format&quot; and &quot;Pipe delimit…&quot; → the summary&#39;s Format block. v1&#39;s &quot;Filter by Created Dates&quot; tick box is dropped: a date in From / To is the filter.</p><h2 id="composition" tabindex="-1">Composition <a class="header-anchor" href="#composition" aria-label="Permalink to &quot;Composition&quot;">​</a></h2><p>ControlScreen shell (cloned from ExportSystem) · RecordSection · Accordion <code>--flush</code> · FieldRow (Input, Select, DatePicker, Checkbox, Radio, lookup) · Radio (presets) · Checkbox (columns) · Input (search) · SegmentedControl · Button (primary / secondary / tertiary xs) · Badge · Alert · Spinner · Table.</p><h2 id="layout-values-all-borrowed-no-new-tokens" tabindex="-1">Layout values (all borrowed; no new tokens) <a class="header-anchor" href="#layout-values-all-borrowed-no-new-tokens" aria-label="Permalink to &quot;Layout values (all borrowed; no new tokens)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th><th>Borrowed from</th></tr></thead><tbody><tr><td>Page and layout gap</td><td><code>spacing-5</code></td><td>Record screens&#39; card gap</td></tr><tr><td>Summary width</td><td><code>size-7</code> (384px)</td><td>— (fits a filter line and three format buttons)</td></tr><tr><td>Summary position</td><td>sticky, <code>top: 0</code>; static under 1024</td><td>—</td></tr><tr><td>Top-level cards</td><td><code>border/card</code>, <code>shadow/2xs</code></td><td>CC top-level card rule</td></tr><tr><td>Scope / group padding</td><td><code>spacing-6</code> (<code>spacing-5</code> under 767)</td><td>RecordSection body padding</td></tr><tr><td>Field rows in a group</td><td><code>spacing-6</code> apart</td><td>RecordSection row gap</td></tr><tr><td>Accordion <code>--flush</code> side padding</td><td><code>spacing-6</code></td><td><strong>Contextual override (Case B)</strong>: flush has none; inside a card it lines up with the card</td></tr><tr><td>Count value</td><td><code>font-fixed-3xl</code> semibold, <code>leading-xl</code></td><td>— (Import&#39;s tiles are a size down)</td></tr><tr><td>Summary blocks</td><td><code>spacing-5</code> above, <code>1px border/secondary</code> top, head min height <code>spacing-7</code></td><td>FactList dividers; xs button height</td></tr><tr><td>Column grid</td><td><code>auto-fill</code>, min <code>size-3</code>, gap <code>spacing-4</code> × <code>spacing-6</code></td><td>ExportSystem target grid</td></tr><tr><td>Picker box</td><td><code>1px border/secondary</code>, <code>radius-md</code>, padding <code>spacing-5</code></td><td>Inner-card rule</td></tr><tr><td>Progress bar</td><td>Import&#39;s meter</td><td>ImportScreen</td></tr></tbody></table><h2 id="responsive-cs-page" tabindex="-1">Responsive (<code>cs-page</code>) <a class="header-anchor" href="#responsive-cs-page" aria-label="Permalink to &quot;Responsive (`cs-page`)&quot;">​</a></h2><p>Under 1024 the summary drops below the work column (not sticky). Under 767 scope / groups pad <code>spacing-5</code>; Recent exports keep File, Status and Download (count, Format, Run by, Started give way); Download goes icon-only. Checked headless at 1440 and 500.</p><h2 id="demo-switches" tabindex="-1">Demo switches <a class="header-anchor" href="#demo-switches" aria-label="Permalink to &quot;Demo switches&quot;">​</a></h2><p><code>?count=0</code> · <code>?cols=custom</code> · <code>?recent=0</code>. Lookups&#39; <strong>Select</strong> buttons are not wired (backend: v1&#39;s pickers); Contact lists (User Export) and Sections (Article Export) are prefilled so the summary has a filter to show.</p><h2 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h2><p><code>HANDOVER.md</code> § Surface: ExportScreen, and <code>grep -rn &quot;TODO(backend:ExportScreen)&quot; src/</code>.</p>',16))])}const q=a(l,[["render",p]]);export{y as __pageData,q as default};
